import { QUESTION_BANK } from './question-bank.js';
const $ = (s, r = document) => r.querySelector(s);
const app = $('#app');
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = v => structuredClone(v);
const bank = id => QUESTION_BANK.find(q => q.id === id);
const uid = () => crypto.randomUUID();
const blank = () => ({view:'home', answers:[], draft:{}, question:bank('q1'), cursor:0, discovery:[], message:'', facts:null, selected:[], focusAnswerIds:[], editOrigin:null, excluded:'', verified:false, consent:false, finalConsent:false, previewDisclosureAccepted:false, result:null, resultInvalidated:false, hadGenerated:false, busy:false, error:null, pending:null, edited:false, deletionPending:false, version:0});
let S = blank();
let server = {loading:true, ready:false, freeAvailable:true, paymentReady:false};
let controller = null;
const RESULT_KEY = 'insosoe:v3:resultId';
const isResultId = value => typeof value === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const savedResultId = () => { try {const id=localStorage.getItem(RESULT_KEY);return isResultId(id)?id:null;} catch {return null;} };
const rememberResult = id => {try {if(isResultId(id))localStorage.setItem(RESULT_KEY,id);else localStorage.removeItem(RESULT_KEY);} catch { /* Storage is optional. */ }};
const P={busy:false,error:'',message:'',callback:null,callbackRoute:'',deletingId:null,leaving:false};
// Capture credentials in memory and remove them before the first render or network request.
if(['/payment/success','/payment/fail'].includes(location.pathname)){
 const params=new URLSearchParams(location.search);P.callbackRoute=location.pathname;
 if(location.pathname==='/payment/success')P.callback={orderId:params.get('orderId')||'',paymentKey:params.get('paymentKey')||'',amount:Number(params.get('amount'))};
 else P.message='결제가 완료되지 않았어요. 이전 결과를 불러오면 다시 시도할 수 있어요.';
 history.replaceState(null,'','/');
}
const canUseFull = () => S.result?.access==='full' && !S.resultInvalidated;
const paymentMode = () => S.result?.purchase?.mode || server.paymentMode || 'disabled';
const paymentReason = () => S.result?.purchase?.disabledReason || server.paymentDisabledReason || '아직 결제를 받을 준비가 되지 않았어요. 지금은 무료 부분 미리보기만 이용할 수 있고, 전문은 열 수 없습니다.';
const canPay = () => S.result?.access==='preview' && !S.resultInvalidated && S.result?.purchase?.ready===true && ['test','live'].includes(paymentMode());

const providerName = () => typeof server.provider === 'object' ? (server.provider?.name || server.provider?.id || '서버 제공 정보 확인 중') : (server.provider || '아직 연결되지 않음');
const available = () => server.ready === true && server.freeAvailable !== false;
const count = text => [...String(text || '')].length;
const apiAnswers = () => S.answers.map(({id,question,answer}) => ({id,question,answer}));
function profile() {
 const p = {purpose:'',organization:'',role:'',posting:'',prompts:[],tone:'',life:[]};
 for (const a of S.answers) {
  if(a.id==='q1') p.purpose=a.answer;
  if(a.id==='q2') p.organization=a.answer;
  if(a.id==='q3') p.role=a.answer;
  if(a.id==='q4') {p.posting=a.form.posting||''; p.prompts=a.form.free ? [] : (a.form.prompts||[]).map((x,i)=>({id:x.id||'p'+(i+1),heading:x.heading.trim(),charLimit:Number(x.charLimit)||0}));}
  if(a.id==='q5') p.life=a.form.values||[];
  if(a.id==='q29') p.tone=a.answer;
 }
 return p;
}
function announce(t) { $('#announce').textContent=t; }
function route(view, replace=false) {S.view=view; history[replace?'replaceState':'pushState']({insosoe:true,view,cursor:S.cursor},''); render();}
function headingFocus(){requestAnimationFrame(()=>$('#main h1')?.focus({preventScroll:true}));}
function logo(){return '<a href="#" class="brand" data-action="home"><img src="/logo.svg" alt="" width="35" height="35"><span>인소서<small>인터뷰엔 자소서</small></span></a>';}
function header(){return '<header class="site-header"><div class="header-inner">'+logo()+'<nav aria-label="주 메뉴">'+(S.view==='home'?'<a href="#how">이용 방법</a><a href="#pricing">이용 요금</a>':'<button class="text-button" data-action="answers">답변 돌아보기</button>')+'<button class="text-button" data-action="privacy">개인정보 안내</button>'+(S.answers.length||S.view!=='home'?'<button class="text-button danger" data-action="delete">내용 삭제</button>':'')+'</nav></div></header>';}
function policyLinks(){return '<a href="/terms.html" target="_blank" rel="noopener noreferrer">이용약관<span class="sr-only"> (새 창)</span></a><a href="/privacy.html" target="_blank" rel="noopener noreferrer">개인정보처리방침<span class="sr-only"> (새 창)</span></a>';}
function footer(){return '<footer class="site-footer"><span>인소서 · 인터뷰엔 자소서</span><span>실제 경험을 담고, 없는 경험은 만들지 않아요.</span><nav class="policy-links" aria-label="이용 및 개인정보 안내">'+policyLinks()+'</nav></footer>';}
function statusBox(){
 if(server.loading)return '<p class="service-note" role="status">이용 가능 여부를 확인하고 있어요.</p>';
 const unavailable=!server.ready||server.freeAvailable===false;
 const paymentUnavailable=server.paymentReady!==true||server.paymentMode==='disabled';
 if(!unavailable&&!paymentUnavailable&&server.paymentMode!=='test')return '';
 return '<div class="notice '+(unavailable||paymentUnavailable?'warning':'')+'"><strong>'+(server.freeAvailable===false?'이 브라우저의 첫 무료 미리보기를 사용했어요.':!server.ready?'지금은 인터뷰를 시작할 수 없어요.':server.paymentMode==='test'?'결제 테스트 환경입니다. 실제 결제가 아니에요.':'전문 열람 결제는 준비 중이에요.')+'</strong><p>'+esc(!server.ready?(server.message||'서비스 연결이 준비되면 시작할 수 있어요. 잠시 후 다시 확인해주세요.'):paymentUnavailable?paymentReason():server.freeAvailable===false?'이전 결과를 불러오거나, 결제한 결과의 복구코드를 사용해주세요.':'테스트 승인 결과는 운영 결제·구매로 인정되지 않습니다.')+'</p><button class="text-button" data-action="status">다시 확인</button></div>';
}
function home(){return '<main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow">무엇을 써야 할지 모르겠을 때, 인소서</p><h1 tabindex="-1">자소서가 막막하다면,<br><span>질문부터 시작해요.</span></h1><p class="hero-description">대단한 경험을 준비해 오지 않아도 괜찮아요.<br>쉬운 질문으로 내가 해낸 일을 찾고,<br>지원하는 곳에 맞는 자기소개서로 연결해요.</p><div class="hero-actions"><button class="button primary large" data-action="start" '+(!S.answers.length&&!available()?'disabled':'')+'>'+(S.answers.length?'이어서 작성하기':'내 경험 찾기 시작')+' <span aria-hidden="true">↗</span></button><p class="offer-line"><b>첫 1건 부분 미리보기 무료</b><br>전문 열람·복사·저장 <b>1건 3,000원</b> · 구독 없음</p><button class="text-button" data-action="restore">이전 결과 불러오기</button></div>'+statusBox()+'</div><div class="hero-art example-card"><div class="example-top"><span class="pill">가상 예시</span><span>실제 이용자·합격 사례가 아닙니다</span></div><div class="example-before"><span class="tiny-label">처음 떠오른 경험</span><p>“카페 알바만 했는데,<br>자소서에 쓸 만한 게 있을까요?”</p></div><div class="example-question"><span>인소서의 질문</span><p>바쁠 때, 일이 덜 꼬이도록<br>내가 바꿔본 건 없었나요?</p></div><div class="example-answer"><span class="tiny-label">가상 답변에서 찾은 소재</span><p>“컵과 뚜껑을 미리 묶어 두고,<br>동료에게 준비 순서를 공유했어요.”</p></div><div class="example-after"><span class="tiny-label">매장 운영 직무에 연결한 문장 예시</span><p>주문이 몰리는 시간에 대비해 컵과 뚜껑을 함께 준비했습니다. 동료와 준비 순서를 공유하며, 반복되는 일을 더 수월하게 하는 방법을 찾았습니다.</p></div><p class="example-foot">실제 글은 내가 확인한 경험과 지원 문항에 따라 달라져요.</p></div></section><div class="purpose-strip wrap"><span>이런 지원을 준비할 때</span><span>취업·이직</span><span>인턴·알바</span><span>직업교육</span><span>대외활동</span><small>대학 신입학 제외</small></div><section class="section wrap" id="how"><div class="section-heading"><p class="eyebrow">빈 문서 앞에서 멈추지 않도록</p><h2>쉽게 답하고, 경험을 찾고,<br>지원할 글까지 완성해요.</h2></div><div class="steps-grid"><article><span class="step-number">1</span><h3>아는 만큼만 답해주세요</h3><p>어디에 지원하는지, 평소 어떤 일을 했는지. 글쓰기 요령이나 AI 지시문은 몰라도 돼요. 총 10~30개 질문을 하나씩 나눠요.</p></article><article><span class="step-number">2</span><h3>지나쳤던 내 경험을 발견해요</h3><p>작은 행동, 내가 내린 판단, 함께 해결한 일. 답변에서 소재를 찾고, 내가 쓸 사실만 직접 선택하고 고쳐요.</p></article><article><span class="step-number">3</span><h3>지원 목적에 맞는 글로 연결해요</h3><p>내가 확인한 경험을 공고·문항과 연결해요. 일부를 무료로 확인하고, 원하면 그 결과 1건의 전문을 열 수 있어요.</p></article></div></section><section class="principles wrap"><div><p class="eyebrow">나를 부풀리지 않는 글쓰기</p><h2>멋진 말보다,<br>내가 실제로 한 일.</h2></div><ul><li><b>기억나지 않으면 넘어가도 괜찮아요.</b><span>짧은 단어나 편한 문장으로 시작하세요.</span></li><li><b>AI 해석은 내 확인을 거쳐요.</b><span>사실과 해석을 구분하고, 원하지 않는 내용은 제외할 수 있어요.</span></li><li><b>내가 한 일이 드러나도록 다듬어요.</b><span>공고·문항과 경험을 연결하고, 본인 역할과 판단을 별도로 검수해요. 제출 전 직접 확인은 필요하며, 정확성과 합격을 보장하지 않습니다.</span></li></ul></section><section class="section wrap" id="pricing"><div class="section-heading"><p class="eyebrow">요금은 시작 전에 분명하게</p><h2>먼저 일부를 확인하고,<br>필요할 때 한 편만.</h2><p>하나의 결과를 미리 보고 여는 방식이에요. 구독이나 자동 결제는 없어요.</p></div><article class="offer-card"><div><span class="pill">첫 익명 브라우저 1건</span><h3>부분 미리보기</h3><p class="price">무료</p><p>경험 인터뷰 · 소재 선택 · 사실 확인<br>완성된 글의 일부만 열람 · 나머지 부분 잠금</p></div><span class="offer-arrow" aria-hidden="true">→</span><div class="offer-unlock"><span class="pill">원할 때 전문 열람</span><h3>그 결과 1건의 전문</h3><p class="price">3,000<small>원 · KRW</small></p><p>전문 열람 · 직접 편집 · 복사 · TXT 저장<br>결제 승인일부터 7일간 서버 보관</p></div></article><div class="pricing-actions"><button class="button primary" data-action="start" '+(!S.answers.length&&!available()?'disabled':'')+'>쉬운 질문부터 시작하기</button><button class="text-button" data-action="recover-dialog">결제한 결과 복구하기</button><button class="text-button" data-action="terms">이용·결제 안내</button></div><p class="fineprint">무료는 익명 브라우저의 첫 생성 1건에 한한 부분 미리보기입니다. 미리보기에서는 전문 편집·복사·저장을 제공하지 않습니다. 개인당 1회 인증이 아니며, 삭제해도 무료 한도는 초기화되지 않습니다. 보관·환불 조건은 이용약관에서 확인해주세요. '+(server.paymentReady!==true?'현재 전문 결제는 준비 중이며 결제를 받지 않습니다.':'')+'</p></section></main>';}
function progress(stage){return '<div class="progress-top"><span class="eyebrow">MY STORY INTERVIEW</span><span>'+S.answers.length+'개 답변 · 최대 30개 질문</span></div><ol class="progress-steps">'+['지원 방향','경험 인터뷰','소재·사실 확인','자기소개서'].map((x,i)=>'<li class="'+(i===stage?'active':i<stage?'done':'')+'" '+(i===stage?'aria-current="step"':'')+'><span>'+(i<stage?'✓':i+1)+'</span>'+x+'</li>').join('')+'</ol>';}
function invalidatedNotice(){return S.resultInvalidated?'<div class="notice warning result-invalid" role="alert"><strong>수정 전 초안과 검수 결과는 더 이상 유효하지 않아요.</strong><p>사실·소재·답변이 변경되었어요. 다시 검수·생성하기 전에는 기존 초안을 제출용으로 사용할 수 없습니다.</p>'+(S.hadGenerated||server.freeAvailable===false?'<p>무료 첫 1건은 이미 이용했습니다. 이 상품은 기존 결과 1건의 전문 열람이며 재생성·재검수 상품이 아니에요. 입력한 내용은 이 페이지에 유지됩니다.</p>':'<p>수정한 사실을 다시 확인하고 새 초안을 생성해주세요.</p>')+'</div>':'';}
function invalidateResult(){if(S.result||S.hadGenerated){S.resultInvalidated=true;const host=$('#main');if(host&&!$('.result-invalid',host)){const box=document.createElement('div');box.innerHTML=invalidatedNotice();host.prepend(box.firstElementChild);}announce('사실이 변경되어 기존 초안과 검수가 무효화됐어요. 다시 검수·생성하기 전에는 제출용으로 사용하지 마세요.');}}
function errorBox(){return S.error?'<div class="error-box" role="alert"><strong>'+esc(S.error.title||'연결을 완료하지 못했어요')+'</strong><p>'+esc(S.error.message)+'</p><small>작성한 답변은 이 화면에 그대로 있어요. 새로고침하지 마세요.</small><p class="subtle">'+(S.error.retryMode==='new'?'답변은 그대로 두고 같은 내용을 다시 처리해요.':'중복 작성을 막기 위해 먼저 앞선 처리 결과를 확인해요.')+'</p>'+((S.error.missing||[]).length?'<ul>'+S.error.missing.map(m=>'<li>'+esc(typeof m==='string'?m:JSON.stringify(m))+'</li>').join('')+'</ul>':'')+'<div class="button-row">'+(S.pending?'<button class="button secondary" data-action="retry">'+(S.error.retryMode==='new'?'새 요청으로 다시 시도':'같은 요청 이어서 확인')+'</button>':'')+'<button class="text-button" data-action="status">서버 연결 확인</button>'+((S.error.status===422||(S.error.missing||[]).length)?'<button class="text-button" data-action="answers">답변 보완하기</button>':'')+'</div></div>':'';}
function sourceDetails(ids,quote){const arr=(ids||[]).map(id=>S.answers.find(a=>a.id===id)).filter(Boolean);return '<details class="source"><summary>근거 원문 보기</summary>'+(quote?'<blockquote>'+esc(quote)+'</blockquote>':'')+(arr.length?arr.map(a=>'<div class="original"><b>'+esc(a.question)+'</b><p>'+esc(a.answer)+'</p></div>').join(''):'<p>연결된 답변 원문을 확인할 수 없어요. 사실로 확정하지 마세요.</p>')+'</details>';}
function side(){return '<aside class="interview-side"><div class="side-head"><span class="eyebrow">STORY NOTES</span><h2>대화에서 찾은 소재 <span>'+S.discovery.length+'</span></h2></div>'+(S.discovery.length?S.discovery.map(d=>'<article class="discovery"><span class="tiny-label">답변에서 발견</span><h3>'+esc(d.label)+'</h3><blockquote>'+esc(d.quote)+'</blockquote>'+sourceDetails([d.answerId])+'</article>').join(''):'<div class="empty-notes"><span aria-hidden="true">“</span><h3>작은 경험도 좋은 시작이에요.</h3><p>이야기를 나누면서 실제 답변에 근거한 소재를 이곳에 모을게요.</p></div>')+'<div class="privacy-note"><b>편하게, 필요한 내용만.</b><p>실명·연락처·주소·주민등록번호는 적지 마세요. 학교 이름이나 부모님의 직업도 필요하지 않아요.</p></div></aside>';}
function shell(content,stage=1){return '<main id="main" class="workspace wrap">'+progress(stage)+errorBox()+invalidatedNotice()+'<div class="interview-layout"><section class="work-card">'+content+'</section>'+side()+'</div></main>';}
function draftFor(q,form){S.question=clone(q); S.draft=clone(form||{text:'',values:[],posting:'',free:false,prompts:[{id:'p1',heading:'',charLimit:500}]});}
function consentHtml(final=false){const key=final?'finalConsent':'consent';return '<label class="check-line consent"><input type="checkbox" data-field="'+key+'" '+(S[key]?'checked':'')+'><span>작성한 답변'+(final?'과 확인한 사실':'')+'을 서버와 <b>'+esc(providerName())+'</b>에 보내 '+(final?'AI 초안 생성 및 검수를':'AI 인터뷰 및 사실 정리를')+' 진행하는 데 동의해요.<small>불필요한 개인정보는 제외해주세요. <button type="button" class="inline-button" data-action="privacy">처리·보관 요약</button> · <a class="inline-button" href="/privacy.html" target="_blank" rel="noopener noreferrer">개인정보처리방침<span class="sr-only"> (새 창)</span></a></small></span></label>';}
function qa(){const q=S.question;const editing=S.cursor<S.answers.length;let field='';if(q.type==='requirements'){field='<label class="field-label" for="posting">지원 공고·안내문 <span>선택</span></label><textarea id="posting" data-field="posting" rows="5" maxlength="6000" placeholder="직무, 필요한 역량, 지원 조건 등 필요한 부분만 붙여넣어 주세요.">'+esc(S.draft.posting)+'</textarea><label class="check-line"><input type="checkbox" data-field="free" '+(S.draft.free?'checked':'')+'>정해진 문항이 없어요 · 자유 형식</label><div class="prompt-list" '+(S.draft.free?'hidden':'')+'><div class="label-row prompt-label"><b>자기소개서 문항</b><span>최대 5개 · 문항별 100~2,000자 · 합계 5,000자 이하</span></div><p id="prompt-total" class="subtle">설정한 글자 수 합계 '+(S.draft.prompts||[]).reduce((sum,p)=>sum+(Number(p.charLimit)||0),0).toLocaleString('ko-KR')+' / 5,000자</p>'+(S.draft.prompts||[]).map((p,i)=>'<div class="prompt-item"><label for="prompt-'+i+'">문항 '+(i+1)+'</label><textarea id="prompt-'+i+'" data-prompt="'+i+'" data-key="heading" rows="2" maxlength="500" placeholder="자기소개서 문항을 그대로 적어주세요.">'+esc(p.heading)+'</textarea><div class="limit-row"><label for="limit-'+i+'">글자 수 제한</label><input id="limit-'+i+'" type="number" min="100" max="2000" step="1" inputmode="numeric" data-prompt="'+i+'" data-key="charLimit" value="'+esc(p.charLimit)+'"><span>자</span><button type="button" class="text-button" data-action="remove-prompt" data-index="'+i+'" '+(S.draft.prompts.length===1?'disabled':'')+'>문항 삭제</button></div></div>').join('')+'<button type="button" class="button secondary add-prompt" data-action="add-prompt" '+(S.draft.prompts?.length>=5?'disabled':'')+'>+ 문항 추가</button></div>';}
 else if(q.type==='choice'||q.type==='multi'){field='<fieldset class="choices"><legend class="sr-only">'+esc(q.title)+'</legend>'+((q.choices||[]).map((v,i)=>'<label class="choice '+((q.type==='multi'?S.draft.values?.includes(v):S.draft.text===v)?'selected':'')+'"><input type="'+(q.type==='multi'?'checkbox':'radio')+'" name="choice" value="'+esc(v)+'" data-choice="'+i+'" '+((q.type==='multi'?S.draft.values?.includes(v):S.draft.text===v)?'checked':'')+'><span>'+esc(v)+'</span></label>').join(''))+'</fieldset>'+(q.id==='q5'?'<p class="subtle">해당하는 생활을 모두 골라주세요. 학교 이름이나 학력은 묻지 않아요.</p>':'');if(!/^q(1|5|29)$/.test(q.id))field+='<label class="field-label" for="answer">다른 일이에요 · 직접 답하기</label><textarea id="answer" data-field="text" rows="3" maxlength="3000">'+esc(S.draft.text&&!(q.choices||[]).includes(S.draft.text)?S.draft.text:'')+'</textarea>';}
 else field='<label class="sr-only" for="answer">나의 답변</label><textarea id="answer" class="answer-input" data-field="text" rows="7" maxlength="'+(['q2','q3'].includes(q.id)?200:3000)+'" placeholder="단어나 짧은 문장으로 편하게 적어주세요.">'+esc(S.draft.text)+'</textarea><div class="answer-meter"><span>멋지게 쓰지 않아도 괜찮아요.</span><span id="input-count">'+count(S.draft.text)+' / '+(['q2','q3'].includes(q.id)?'200':'3,000')+'</span></div>';
 const anchor=(q.sourceAnswerIds||[]).map(id=>S.answers.find(a=>a.id===id)).filter(Boolean);
 return shell('<div class="question-meta"><span class="pill">'+(q.id==='q29'?'마지막 말투 선택':S.cursor<5?'먼저, 지원 방향부터':'AI 경험 인터뷰')+'</span><span>'+Math.min(30,S.cursor+1)+'번째 질문</span></div>'+(editing?'<div class="notice">이전 답변을 수정 중이에요. 변경 후 계속하면 이후 질문·사실 카드·초안은 무효화되고 새로 만들어집니다.</div>':'')+(S.message&&S.cursor>=5?'<div class="coach-message"><span class="coach-avatar" aria-hidden="true">i.</span><p>'+esc(S.message)+'</p></div>':'')+(anchor.length?'<div class="experience-anchor"><span>지금 더 알아보는 경험</span><strong>'+esc(anchor[0].question)+'</strong><p>'+esc(anchor[0].answer)+'</p></div>':'')+'<h1 tabindex="-1">'+esc(q.title)+'</h1><p class="question-helper">'+esc(q.helper||'짧게 답해도 괜찮아요. 떠오르지 않으면 넘어가도 됩니다.')+'</p><form id="question-form">'+field+(q.id==='q5'?consentHtml():'')+'<div id="form-error" class="field-error" role="alert"></div><div class="question-actions"><button class="text-button" type="button" data-action="back" '+(S.cursor===0?'disabled':'')+'>← 이전 질문</button><button class="button primary" type="submit">'+(q.id==='q29'?'소재와 사실 정리하기':S.cursor<4?'다음 질문':'계속 이야기하기')+' <span aria-hidden="true">→</span></button></div>'+(!['q1','q4','q5','q29'].includes(q.id)?'<div class="skip-options" aria-label="답변하기 어려울 때"><button type="button" data-action="skip" data-value="없어요">없어요</button><button type="button" data-action="skip" data-value="잘 기억나지 않아요">잘 기억나지 않아요</button><button type="button" data-action="skip" data-value="아직 모르겠어요">아직 모르겠어요</button><button type="button" data-action="skip" data-value="건너뛸게요">건너뛸게요</button></div>':'')+'</form>',S.cursor<5?0:q.id==='q29'?2:1);}
function waiting(){return shell('<div class="waiting"><div class="orbit '+(S.busy?'spinning':'')+'" aria-hidden="true">i.</div><p class="eyebrow">'+(S.pending?.action==='generate'?'WRITING YOUR STORY':'READING YOUR STORY')+'</p><h1 tabindex="-1">'+(S.error?'이야기는 그대로 기다리고 있어요.':S.pending?.action==='generate'?'당신의 사실로 쓰고, 다시 검수하고 있어요.':S.pending?.action==='facts'?'이야기에서 사실과 소재를 정리하고 있어요.':'방금 답변을 읽고 다음 질문을 고르고 있어요.')+'</h1><p>'+(S.error?'위의 다시 시도 버튼으로 같은 요청을 이어갈 수 있어요.':'실제 AI가 처리 중이에요. 잠시 시간이 걸릴 수 있어요.')+'</p><p class="subtle">이 페이지를 닫거나 새로고침하면 작성 내용이 사라져요.</p><button class="text-button" data-action="answers" '+(S.busy?'disabled':'')+'>내 답변 돌아보기</button></div>',S.pending?.action==='generate'?3:S.pending?.action==='facts'?2:1);}
function candidatePage(){const cs=S.facts?.candidates||[];return shell('<span class="pill">마무리 · 사용할 소재 선택</span><h1 tabindex="-1">'+esc(bank('q28').title)+'</h1><p class="question-helper">AI가 실제 답변에서 찾은 후보예요. 쓰고 싶은 소재를 골라주세요. 선택이 역량이나 성과의 검증을 의미하지는 않아요.</p><div class="candidate-list">'+(cs.length?cs.map(c=>'<article class="candidate"><label class="check-line"><input type="checkbox" data-candidate="'+esc(c.id)+'" '+(S.selected.includes(c.id)?'checked':'')+'><span><strong>'+esc(c.title)+'</strong><small>'+esc(c.summary)+'</small></span></label>'+sourceDetails(c.answerIds)+'</article>').join(''):'<div class="notice">지금 답변에서는 충분한 소재 후보를 찾지 못했어요. 없는 경험을 만들지 않고, 확인 가능한 사실만 검토합니다.</div>')+'</div><label class="check-line"><input type="checkbox" data-field="noCandidate" '+(S.noCandidate?'checked':'')+'>맞는 내용이 없어요 / 아직 모르겠어요</label><div id="form-error" class="field-error" role="alert"></div><div class="question-actions"><button class="text-button" data-action="answers">답변 돌아보기</button><button class="button primary" data-action="confirm-candidates">이 소재로 사실 확인 →</button></div>',2);}
function factCard(f,i){return '<article class="fact-card '+(!f.included?'excluded':'')+'"><div class="fact-top"><label class="check-line"><input type="checkbox" data-fact="'+i+'" data-key="included" '+(f.included?'checked':'')+'><span>자기소개서에 포함</span></label><span class="tiny-label">'+(f.kind==='interpretation'?'AI 해석 · 본인 확인 필요':'사용자가 말한 사실')+'</span></div><label class="sr-only" for="fact-'+i+'">'+(f.kind==='interpretation'?'AI 해석':'사실')+' 수정</label><textarea id="fact-'+i+'" data-fact="'+i+'" data-key="text" rows="3" maxlength="1000" '+(!f.included?'disabled':'')+'>'+esc(f.text)+'</textarea>'+sourceDetails([f.answerId],f.quote)+'</article>';}
function review(){let fs=S.facts?.facts||[];const missing=S.facts?.missing||[];return shell('<span class="pill">마지막 · 사실 확인</span><h1 tabindex="-1">'+esc(bank('q30').title)+'</h1><p class="question-helper">사실은 원문과 비교하고, AI 해석은 내 생각과 맞는지 확인해주세요. 각 카드를 직접 고치거나 체크를 해제해 제외할 수 있어요.</p>'+(missing.length||S.facts?.readiness==='insufficient'?'<div class="notice warning"><b>조금 더 확인이 필요해요</b><p>'+esc(S.facts.reason||'소재가 부족한 부분은 지어내지 않습니다.')+'</p><ul>'+missing.map(m=>'<li>'+esc(typeof m==='string'?m:JSON.stringify(m))+'</li>').join('')+'</ul><button class="text-button" data-action="answers">답변 보완하기</button></div>':'')+'<section class="fact-group"><h2>내가 말한 사실 <span>'+fs.filter(f=>f.kind==='fact').length+'</span></h2>'+fs.map((f,i)=>f.kind==='fact'?factCard(f,i):'').join('')+'</section><section class="fact-group interpretations"><h2>AI가 해석한 내용 <span>'+fs.filter(f=>f.kind==='interpretation').length+'</span></h2><p class="subtle">강점이나 지원 업무와의 연결은 AI의 해석이에요. 동의할 때만 포함하세요.</p>'+fs.map((f,i)=>f.kind==='interpretation'?factCard(f,i):'').join('')+'</section><label class="field-label" for="exclusions">추가로 넣고 싶지 않은 내용 <span>선택</span></label><textarea id="exclusions" data-field="excluded" rows="3" maxlength="2000" placeholder="예: 학교 이름, 특정 경험, 과장된 표현은 빼주세요.">'+esc(S.excluded)+'</textarea><div class="final-confirm"><label class="check-line"><input type="checkbox" data-field="verified" '+(S.verified?'checked':'')+'><span>포함된 사실과 AI 해석을 확인했어요. 역할·수치·성과가 실제 경험과 다르지 않은지 검토했어요.</span></label>'+consentHtml(true)+previewConsentHtml()+'</div><div id="form-error" class="field-error" role="alert"></div>'+(S.result?'<button class="text-button" data-action="result-back">기존 결과로 돌아가기 →</button>':'')+'<div class="question-actions"><button class="text-button" data-action="candidates-back">← 소재 다시 선택</button><button class="button primary" data-action="generate">첫 1건 무료 부분 미리보기 만들기 →</button></div><p class="fineprint">생성 후에도 제출 전에는 직접 읽고 확인해주세요. AI는 사실을 잘못 해석하거나 실수할 수 있어요.</p>',2);}
function sectionLimit(section){const limit=Number(section?.charLimit);return Number.isInteger(limit)&&limit>0?limit:null;}
function evidenceCard(f){if(!f||typeof f.text!=='string')return '';const interpretation=f.kind==='interpretation';return '<article class="original evidence-card"><span class="evidence-tag">'+(interpretation?'AI 해석 · 이용자가 확인한 내용':'본인 경험 · 이용자가 확인한 사실')+'</span>'+(f.edited?'<span class="evidence-tag evidence-corrected">이용자가 직접 정정한 내용</span>':'')+'<b>'+esc(f.text)+'</b>'+(f.edited&&typeof f.originalText==='string'&&f.originalText!==f.text?'<details class="source"><summary>정정 전 AI 정리 문장</summary><p>'+esc(f.originalText)+'</p></details>':'')+(typeof f.quote==='string'&&f.quote?'<span class="evidence-label">답변에서 인용한 원문 일부</span><blockquote class="evidence-quote">'+esc(f.quote)+'</blockquote>':'<p class="subtle">연결된 원문 인용이 제공되지 않았어요. 실제 경험과 맞는지 직접 확인해주세요.</p>')+'</article>';}
function resultEvidence(){if(S.result?.access!=='full'||!Array.isArray(S.result.sources)||!S.result.sources.length)return '';return '<details class="source evidence-list"><summary>사용한 경험 근거 · '+S.result.sources.length+'개</summary><p class="subtle">결과 작성에 사용한 확인 사실과 AI 해석입니다. 정정 내용과 원문 인용을 구분해 보여드려요. 전체 인터뷰 답변을 복구한 것은 아닙니다.</p>'+S.result.sources.map(evidenceCard).join('')+'</details>';}
function result(){
 const r=S.result; const full=canUseFull(); const blocked=full?'':' disabled';
 return '<main id="main" class="result-workspace wrap">'+progress(3)+errorBox()+invalidatedNotice()+paymentNotice()+'<div class="result-heading"><div><span class="pill">'+(r.access==='full'?'전문 열람 · 결제 확인됨':'첫 1건 무료 부분 미리보기')+'</span><h1 tabindex="-1">작은 경험이, 지원할 글로.</h1><p>'+(r.access==='full'?'직접 읽고 고쳐서 내 말로 완성하세요.':'일부 문장만 공개됩니다. 전문 열람·복사·저장은 이 결과 1건에 3,000원이에요.')+'</p></div><div class="button-row"><button class="button secondary" data-action="copy-all"'+blocked+'>전체 복사</button><button class="button primary" data-action="download"'+blocked+'>TXT 저장 ↓</button></div></div><div class="result-layout"><section class="result-sections">'+r.sections.map((s,i)=>{
 const limit=sectionLimit(s);
 let content='';
 if(r.access==='full')content='<textarea id="section-'+i+'" data-section="'+i+'" rows="14" aria-describedby="count-'+i+'" '+(!full?'readonly':'')+'>'+esc(s.text)+'</textarea><div id="count-'+i+'" class="result-count '+(limit&&count(s.text)>limit?'over':'')+'">'+count(s.text)+'자'+(limit?' / '+limit+'자 제한':'')+' <span>공백 포함 · 제외 '+count(s.text.replace(/\s/g,''))+'자</span></div><details class="source result-source"><summary>이 문장의 근거 · '+(s.sourceFactIds||[]).length+'개 사실 카드</summary>'+((s.sourceFactIds||[]).map(id=>{const f=r.sources?.find(x=>x.id===id)||S.facts?.facts?.find(x=>x.id===id);return f?evidenceCard(f):'<p>연결된 경험 근거를 확인할 수 없어요. 전체 인터뷰 답변은 복원되지 않으므로 실제 경험과 맞는지 직접 확인해주세요.</p>';}).join('')||'<p>연결된 사실 카드를 확인할 수 없어요. 제출 전 직접 확인해주세요.</p>')+'</details>';
 else content='<div class="preview-text" aria-label="부분 미리보기">'+s.segments.map(seg=>seg.kind==='visible'?'<p>'+esc(seg.text)+'</p>':'<div class="locked-block"><div class="locked-lines" aria-hidden="true">'+Array.from({length:Math.max(2,Math.min(7,seg.lines||3))},()=>'<span></span>').join('')+'</div><p class="locked-label">전문 열람 후 확인할 수 있는 부분입니다</p></div>').join('')+'</div><p class="result-count">전체 '+Number(s.charCount||0).toLocaleString('ko-KR')+'자'+(limit?' / '+limit+'자 제한':'')+' · 일부만 공개</p>';
 return '<article class="result-section"><div class="label-row"><label '+(r.access==='full'?'for="section-'+i+'"':'')+'><span class="section-no">0'+(i+1)+'</span>'+esc(s.heading)+'</label><button class="text-button" data-action="copy-section" data-index="'+i+'"'+blocked+'>복사</button></div>'+content+'</article>';
 }).join('')+resultEvidence()+(r.access==='preview'?'<p class="subtle">잠긴 영역은 글이 아닌 자리표시자예요. 미리보기에서는 편집·복사·저장을 제공하지 않으며, 보이는 문장의 캡처나 필사까지 막을 수는 없습니다.</p>':'')+'</section><aside class="result-aside">'+(r.access==='preview'?unlockPanel():'<div class="purchase-panel"><span class="pill">'+(paymentMode()==='test'?'테스트 승인 결과':'전문 열람 가능')+'</span><h2>내 글, 따로 보관하세요.</h2><p>결제한 결과는 승인일부터 7일간 보관합니다. 다른 브라우저에서는 복구코드로 찾을 수 있어요.</p>'+(r.recoveryCode?'<button class="button secondary" data-action="recovery-code">복구코드 확인·복사</button>':'')+'<button class="text-button" data-action="restore">결제 상태·결과 다시 확인</button></div>')+'<section class="quality-panel"><p class="eyebrow">제출 전 확인</p><h2>'+(S.resultInvalidated?'무효화된 이전 검수':'글의 준비도 점검')+'</h2><p id="edited-note" class="notice" '+(!S.edited?'hidden':'')+'>직접 편집한 내용에는 아래 AI 검수가 적용되지 않아요. 검수는 처음 받은 결과 기준입니다.</p>'+((r.quality?.checks||[]).map(c=>'<div class="quality-check '+(c.status==='pass'?'pass':'warn')+'"><span aria-hidden="true">'+(c.status==='pass'?'✓':'!')+'</span><div><b>'+esc(c.label)+'</b><p>'+esc(r.access==='full'?c.detail:(c.status==='pass'?'확인됨':'직접 확인 필요'))+'</p></div></div>').join('')||'<p class="subtle">상세 점검 항목이 제공되지 않았어요.</p>')+(r.access==='full'&&(r.quality?.warnings||[]).length?'<div class="notice warning"><b>제출 전 주의사항</b><ul>'+r.quality.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div>':'')+'<p class="quality-note">점검은 사실·문항·표현의 준비도를 살피는 AI 검수입니다. 합격 확률이나 채용 평가가 아니며, 정확성과 합격을 보장하지 않습니다.</p>'+(r.note?'<p class="quality-note">'+esc(r.note)+'</p>':'')+(S.facts?'<button class="text-button" data-action="facts-back">확인한 사실 다시 보기</button>':'')+'</section></aside></div><div class="result-bottom"><p>'+expiryText()+'</p><button class="text-button" data-action="terms">이용·결제 안내</button></div></main>';
}
function render(){app.innerHTML=header()+({home,qa,waiting,candidates:candidatePage,review,result,payment:paymentPage}[S.view]||home)()+footer();app.setAttribute('aria-busy',String(S.busy));headingFocus();}
