 const old=S.answers[S.cursor];if(old&&old.answer===answer&&JSON.stringify(old.form)===JSON.stringify(d)){const origin=S.editOrigin;S.editOrigin=null;if(origin){S.cursor=origin.cursor;draftFor(origin.question,origin.draft);route(origin.view);}else route(S.result?'result':S.facts?'review':S.pending?'waiting':'qa');return;}
 if(old){S.answers=S.answers.slice(0,S.cursor);resetDerived();}S.editOrigin=null;
