async function requestAI(action,retry=false){if(S.busy)return;if(!S.consent){formError('AI 전송 동의가 필요해요.');return;}
 if(!retry){const payload={action,requestId:uid(),consent:true,product:'free',offerVersion:'v3-preview-3000',profile:profile(),answers:apiAnswers()};if(action==='generate'){payload.previewDisclosureAccepted=true;payload.selectedCandidates=(S.facts.candidates||[]).filter(c=>S.selected.includes(c.id)).map(({id,title,answerIds})=>({id,title,answerIds}));payload.focusAnswerIds=S.focusAnswerIds||[];payload.facts=S.facts.facts.filter(f=>f.included).map(({included,...f})=>f);payload.exclusions=S.excluded;payload.verified=true;}S.pending=payload;}
 if(!S.pending)return;if(retry&&S.error?.retryMode==='new'){S.pending={...S.pending,requestId:uid()};}const body=S.pending;S.busy=true;S.error=null;route('waiting');const epoch=S.version;controller=new AbortController();const timer=setTimeout(()=>controller?.abort(),235000);let responded=false;
 try{const response=await fetch('/api/insosoe',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});responded=true;let data;try{data=await response.json();}catch{throw new Error('서버 응답을 읽을 수 없어요. 아래 버튼으로 다시 시도해주세요.');}if(epoch!==S.version)return;if(!response.ok)throw Object.assign(new Error(data.error||'AI 요청을 완료하지 못했어요.'),{code:data.code,retryable:data.retryable,missing:data.missing,status:response.status});if(data.source!=='ai')throw new Error('실제 AI 출처를 확인하지 못해 결과를 표시하지 않았어요.');
 if(action==='interview'){
 S.message=String(data.message||'');const found=(data.discovery||[]).filter(d=>d.label&&d.quote&&S.answers.some(a=>a.id===d.answerId&&a.answer.includes(d.quote)));for(const d of found){if(!S.discovery.some(x=>x.answerId===d.answerId&&x.quote===d.quote))S.discovery.push(d);}
 const ended=(data.ready&&S.answers.length>=8)||S.answers.length>=27||['q28','q29','q30'].includes(data.next?.id);if(ended&&S.answers.length>=8){S.pending=null;S.busy=false;openQuestion(bank('q29'));}
 else {if(!data.next?.title)throw new Error('다음 질문이 아직 준비되지 않았어요. 답변은 보존되어 있어요.');if(S.answers.some(a=>a.id===data.next.id||a.question===data.next.title))throw new Error('이미 답한 질문이 돌아왔어요. 아래 버튼으로 다시 시도하거나 서버 상태를 확인해주세요.');if(!data.next.id)throw new Error('질문 식별자가 누락되어 인터뷰를 멈췄어요.');S.pending=null;S.busy=false;openQuestion({...data.next,type:data.next.type==='choice'?'choice':'text'});}
 }else if(action==='facts'){
 if(!Array.isArray(data.facts)||!Array.isArray(data.candidates))throw new Error('사실 검토 응답의 형식이 올바르지 않아요.');S.facts={...data,facts:data.facts.map(f=>({...f,originalText:f.text,edited:false,included:false}))};S.selected=[];S.noCandidate=false;S.pending=null;S.busy=false;route('candidates');
 }else{acceptResult(data);S.edited=false;S.resultInvalidated=false;S.hadGenerated=true;S.pending=null;S.busy=false;server.freeAvailable=false;route('result');}
 }catch(e){if(epoch!==S.version)return;S.busy=false;S.error={title:e.code==='FREE_USED'?'무료 이용 상태를 확인해주세요':'연결을 완료하지 못했어요',message:e.name==='AbortError'?'응답 대기 시간이 길어졌어요. 다시 확인하면 중복 작성을 막으면서 결과를 기다릴 수 있어요.':e.message,retryable:e.retryable,code:e.code,missing:Array.isArray(e.missing)?e.missing:[],status:e.status,retryMode:!responded||e.name==='AbortError'||controller?.signal.aborted||e.code==='REQUEST_IN_PROGRESS'?'same':'new'};render();announce('AI 연결 오류. 작성한 답변은 보존되어 있어요.');}finally{clearTimeout(timer);if(epoch===S.version){S.busy=false;app.setAttribute('aria-busy','false');}}}
function confirmCandidates(){if(!S.selected.length&&!S.noCandidate){formError('사용할 소재를 고르거나, 맞는 내용이 없음을 선택해주세요.');return;}const chosen=(S.facts.candidates||[]).filter(c=>S.selected.includes(c.id));const answer=S.noCandidate?'선택한 소재 없음':'선택한 소재 ID: '+chosen.map(c=>c.id).join(', ');const previous=S.answers.find(a=>a.id==='q28');if(previous&&previous.answer!==answer)invalidateResult();S.focusAnswerIds=[...new Set(chosen.flatMap(c=>c.answerIds||[]))];if(!previous||previous.answer!==answer){for(const f of S.facts.facts){f.included=f.kind==='fact'&&S.focusAnswerIds.includes(f.answerId)&&!!f.quote&&S.answers.some(a=>a.id===f.answerId&&a.answer.includes(f.quote));}}S.answers=S.answers.filter(a=>a.id!=='q28'&&a.id!=='q30');S.answers.push({id:'q28',question:bank('q28').title,answer,form:{text:answer},q:bank('q28')});S.verified=false;S.finalConsent=false;route('review');}
async function generate(){if(S.hadGenerated||server.freeAvailable===false){formError(S.resultInvalidated?'사실이나 답변이 변경되어 기존 초안은 무효화됐어요. 첫 무료 미리보기는 이미 사용했고, 전문 열람 결제에는 재생성·재검수가 포함되지 않습니다.':'첫 무료 미리보기 1건은 이미 사용했어요. 이전 결과를 불러와 확인해주세요. 전문 열람 결제에는 새 글 생성이 포함되지 않습니다.');return;}if(!S.verified||!S.finalConsent||!S.previewDisclosureAccepted){formError('사실 확인, AI 전송, 무료 미리보기·유료 전문 안내를 모두 확인해주세요.');return;}const f=S.facts.facts.filter(f=>f.included);if(!f.length||f.some(x=>!x.text.trim())){formError('내용이 있는 사실 카드를 최소 하나 포함해주세요.');return;}const confirmation='포함할 사실과 AI 해석을 원문과 비교해 확인했고, 역할·수치·성과가 실제 경험과 다른지 검토했습니다.'+(S.excluded?' 추가 제외 사항: '+S.excluded:'');S.answers=S.answers.filter(a=>a.id!=='q30');if(S.answers.length>=30){formError('전체 질문은 사실 확인을 포함해 최대 30개예요. 이전 답변을 확인해주세요.');return;}S.answers.push({id:'q30',question:bank('q30').title,answer:confirmation,form:{text:confirmation},q:bank('q30')});await requestAI('generate');}
