const dlgState={opener:null,openerAction:'',view:'',inerted:null};
const dlgFocusables=d=>[...d.querySelectorAll('a[href],button,input,select,textarea,summary,[tabindex]')].filter(el=>!el.disabled&&el.tabIndex>=0&&!el.hidden&&!el.closest('[hidden]')&&el.getClientRects().length>0);
