app.addEventListener('invalid',e=>{if(e.target.dataset.key==='charLimit'){formError('문항별 글자 수 제한은 100~2,000자 사이의 정수로 입력해주세요.');}},true);
app.addEventListener('submit',e=>{if(e.target.id==='question-form'){e.preventDefault();commit();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){const k=t.dataset.field;const val=t.type==='checkbox'?t.checked:t.value;if(['text','posting','free'].includes(k))S.draft[k]=val;else S[k]=val;if(k==='text'&&$('#input-count'))$('#input-count').textContent=count(t.value)+' / '+(['q2','q3'].includes(S.question.id)?'200':'3,000');if(k==='excluded'){invalidateResult();S.verified=false;S.finalConsent=false;for(const x of ['verified','finalConsent']){const n=$('[data-field="'+x+'"]');if(n)n.checked=false;}}}if(t.dataset.prompt!==undefined){S.draft.prompts[Number(t.dataset.prompt)][t.dataset.key]=t.value;const total=S.draft.prompts.reduce((sum,p)=>sum+(Number(p.charLimit)||0),0);const meter=$('#prompt-total');if(meter){meter.textContent='설정한 글자 수 합계 '+total.toLocaleString('ko-KR')+' / 5,000자'+(total>5000?' · 합계를 줄여주세요':'');meter.classList.toggle('over',total>5000);}}if(t.dataset.fact!==undefined){invalidateResult();const f=S.facts.facts[Number(t.dataset.fact)];f[t.dataset.key]=t.type==='checkbox'?t.checked:t.value;if(t.dataset.key==='text')f.edited=f.text!==f.originalText;S.verified=false;S.finalConsent=false;for(const x of ['verified','finalConsent']){const n=$('[data-field="'+x+'"]');if(n)n.checked=false;}}if(t.dataset.section!==undefined){if(!canUseFull())return;const i=Number(t.dataset.section);S.result.sections[i].text=t.value;S.edited=true;$('#edited-note').hidden=false;const limit=sectionLimit(S.result.sections[i]);const el=$('#count-'+i);el.classList.toggle('over',!!limit&&count(t.value)>limit);el.innerHTML=count(t.value)+'자'+(limit?' / '+limit+'자 제한':'')+' <span>공백 포함 · 제외 '+count(t.value.replace(/\s/g,''))+'자</span>';}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.choice!==undefined){if(S.question.type==='multi'){S.draft.values=[...document.querySelectorAll('[data-choice]:checked')].map(el=>el.value);}else S.draft.text=t.value;document.querySelectorAll('.choice').forEach(el=>el.classList.toggle('selected',$('input',el).checked));}if(t.dataset.field==='free')$('.prompt-list').hidden=t.checked;if(t.dataset.candidate){S.noCandidate=false;const n=$('[data-field="noCandidate"]');if(n)n.checked=false;if(t.checked)S.selected.push(t.dataset.candidate);else S.selected=S.selected.filter(x=>x!==t.dataset.candidate);}if(t.dataset.field==='noCandidate'&&t.checked){S.selected=[];document.querySelectorAll('[data-candidate]').forEach(el=>el.checked=false);}if(t.dataset.fact!==undefined&&t.dataset.key==='included'){const card=t.closest('.fact-card');card.classList.toggle('excluded',!t.checked);$('textarea',card).disabled=!t.checked;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;if(b.disabled)return;if(P.busy&&!['privacy','close-dialog'].includes(a))return;if(!canUseFull()&&['copy-all','copy-section','download'].includes(a)){announce('서버에서 확인된 유효한 전문 결과에서만 복사·저장을 사용할 수 있어요.');return;}if(S.busy&&!['privacy','close-dialog','delete','confirm-delete','home'].includes(a))return;
 if(a==='start'){if(S.answers.length){route(S.pending?'waiting':S.result?'result':S.facts?'review':'qa');return;}if(!available()){await checkStatus();return;}startDialog();}
 if(a==='begin'){if(!$('#start-accept')?.checked){$('#start-error').textContent='무료 미리보기와 유료 전문 조건을 확인해주세요.';return;}$('#dialog').close();draftFor(bank('q1'));S.cursor=0;route('qa');}
 if(a==='home'){if(S.busy)return;route('home');}
 if(a==='status')await checkStatus();
 if(a==='privacy')privacy();if(a==='answers')answersDialog();if(a==='close-dialog')$('#dialog').close();
 if(a==='add-prompt'){if(S.draft.prompts.length<5){S.draft.prompts.push({id:'p'+uid(),heading:'',charLimit:500});render();}}
 if(a==='remove-prompt'){S.draft.prompts.splice(Number(b.dataset.index),1);render();}
 if(a==='skip')await commit(b.dataset.value);
 if(a==='back'){if(S.cursor>0)editAnswer(S.cursor-1);}
 if(a==='edit-answer'){$('#dialog').close();editAnswer(Number(b.dataset.index));}
 if(a==='review-confirmation'){$('#dialog').close();route('review');}
 if(a==='edit-candidates'){$('#dialog').close();route('candidates');}
 if(a==='retry'&&S.pending)await requestAI(S.pending.action,true);
 if(a==='confirm-candidates')confirmCandidates();
 if(a==='candidates-back')route('candidates');
 if(a==='facts-back'&&S.facts)route('review');
 if(a==='result-back'&&S.result)route('result');
 if(a==='generate')await generate();
 if(a==='copy-all')await copyText(fullText());
 if(a==='copy-section')await copyText(S.result.sections[Number(b.dataset.index)].text);
 if(a==='download'){const blob=new Blob(['\ufeff'+fullText()],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='인소서_자기소개서.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('TXT 파일을 내려받았어요');}
 if(a==='delete')openDialog('<h2 id="dialog-title">작성 내용을 삭제할까요?</h2><p>답변·사실 카드·결과를 이 브라우저에서 비우고, 서버 결과와 복구권한 삭제를 요청합니다. 되돌릴 수 없고 무료 한도는 초기화되지 않습니다. 내용 삭제는 환불이 아니며 결제 거래기록은 별도로 보관됩니다.</p><div class="button-row"><button class="button secondary" data-action="close-dialog">돌아가기</button><button class="button destructive" data-action="confirm-delete">내용 삭제</button></div>');
 if(a==='confirm-delete'||a==='delete-server')await erase();
});
window.addEventListener('popstate',e=>{if(S.busy){history.pushState({insosoe:true,view:S.view,cursor:S.cursor},'');announce('AI 처리 중이에요. 완료 후 이전 질문으로 돌아갈 수 있어요.');return;}const h=e.state;if(!h?.insosoe){S.view='home';render();return;}if(h.view==='qa'){const a=S.answers[h.cursor];if(a){S.cursor=h.cursor;draftFor(a.q,a.form);S.view='qa';}else if(h.cursor===S.answers.length){S.view='qa';}else S.view='home';}else if(h.view==='result'&&!S.result)S.view='home';else if(['review','candidates'].includes(h.view)&&!S.facts)S.view='home';else if(h.view==='waiting')S.view=S.result?'result':S.facts?'review':'qa';else S.view=h.view;render();});
window.addEventListener('beforeunload',e=>{if(!P.leaving&&(S.answers.length||S.draft.text||S.draft.posting)){e.preventDefault();e.returnValue='';}});

function previewConsentHtml(){return '<div class="notice"><strong>첫 1건 부분 미리보기 무료 · 전문 1건 3,000원</strong><p>생성한 글 일부만 무료로 공개됩니다. 전문 편집·복사·저장은 별도 결제 후 사용할 수 있어요. 구독·자동 결제는 없으며, 생성하면 이 브라우저의 첫 무료 1건을 사용합니다.</p>'+(server.paymentReady!==true?'<p class="danger">'+esc(paymentReason())+'</p>':'')+'</div><label class="check-line"><input type="checkbox" data-field="previewDisclosureAccepted" '+(S.previewDisclosureAccepted?'checked':'')+'><span>부분 미리보기와 1건 3,000원 전문 열람 조건을 확인했어요. <a class="inline-button" href="/terms.html" target="_blank" rel="noopener noreferrer">이용약관<span class="sr-only"> (새 창)</span></a></span></label>';}
function startDialog(){openDialog('<p class="eyebrow">시작 전 확인</p><h2 id="dialog-title">쉬운 질문으로 내 경험을 찾아요</h2><p>총 10~30개 질문에 답하고, 쓸 소재와 사실을 직접 고릅니다.</p><div class="notice"><strong>첫 1건 부분 미리보기 무료</strong><p>전문 열람·편집·복사·저장은 그 결과 1건에 <b>3,000원</b>입니다. 구독·자동 결제는 없어요. 무료 이용은 익명 브라우저 기준으로 개인당 1회 인증이 아니며 삭제해도 초기화되지 않아요.</p></div>'+(server.paymentReady!==true?'<div class="notice warning"><strong>지금은 전문 결제가 불가능해요.</strong><p>'+esc(paymentReason())+'</p></div>':server.paymentMode==='test'?'<div class="notice warning">현재 테스트 환경이며 실제 구매·결제가 아닙니다.</div>':'')+'<p>답변은 외부 AI 처리업체로 전송됩니다. 전송 전 동의를 받으며, 민감한 개인정보는 적지 마세요.</p><label class="check-line consent"><input id="start-accept" type="checkbox"><span>무료는 일부만 미리보기이며 전문 1건은 3,000원이라는 점'+(server.paymentReady!==true?'과 현재 결제 불가 상태':'')+'를 확인했어요.</span></label><p id="start-error" class="field-error" role="alert"></p><div class="button-row"><button class="button primary" data-action="begin">첫 질문 보기</button><button class="text-button" data-action="privacy">처리·보관 안내</button></div><nav class="policy-links dialog-policy-links" aria-label="시작 전 정책 확인">'+policyLinks()+'</nav>');}
function expiryText(){const date=new Date(S.result?.purchase?.expiresAt||'');return Number.isFinite(date.getTime())?'결과 보관 기한: '+date.toLocaleString('ko-KR'):'미결제 최대 24시간 · 결제 확인 대기 최대 7일 · 결제 결과 승인일부터 7일 보관';}
function paymentNotice(){return (P.busy?'<div class="notice" role="status">결제 상태를 서버에서 확인하고 있어요. 전문은 확인이 완료된 뒤에만 열립니다.</div>':'')+(P.error?'<div class="error-box" role="alert"><strong>결과를 아직 확인하지 못했어요.</strong><p>'+esc(P.error)+'</p><div class="button-row">'+(P.callback?'<button class="button secondary" data-action="confirm-payment">같은 결제 승인 다시 확인</button>':'')+'<button class="text-button" data-action="restore">이전 결과 다시 확인</button></div></div>':'')+(P.message?'<div class="notice" role="status">'+esc(P.message)+'</div>':'');}
function unlockPanel(){return '<section class="purchase-panel"><span class="pill">구독 없이 이 결과 1건만</span><h2>내 글의 나머지도 확인하기</h2><p class="price">3,000<small>원 · KRW</small></p><p>전문 열람 · 편집 · 복사 · TXT 저장</p>'+(!canPay()?'<div class="notice warning">'+esc(S.resultInvalidated?'수정 전 결과는 유효하지 않아 결제할 수 없어요.':paymentReason())+'</div>':paymentMode()==='test'?'<div class="notice warning"><strong>테스트 결제</strong><p>실제 청구가 없는 개발 테스트이며 운영 구매로 인정되지 않습니다.</p></div>':'')+'<button class="button primary" data-action="checkout" '+(!canPay()||P.busy?'disabled':'')+'>'+(paymentMode()==='test'?'테스트 전문 열람 확인':'3,000원으로 전문 열람')+'</button><button class="text-button" data-action="restore">이미 결제했다면 상태 다시 확인</button><p class="fineprint">새 글 생성이나 재검수 상품이 아닙니다. '+expiryText()+'</p></section>';}
function legalHtml(){const legal=server.paymentLegal;if(!legal||typeof legal!=='object')return '<p>사업자·연락처·거래기록 보관·환불 정책이 아직 제공되지 않았습니다. 조건이 준비되기 전에는 실제 결제를 받지 않습니다.</p>';const labels={merchantName:'상호',businessName:'사업자명',representative:'대표자',businessRegistrationNumber:'사업자등록번호',businessNumber:'사업자등록번호',mailOrderNumber:'통신판매업 신고번호',commerceNumber:'통신판매업 신고번호',phone:'문의 전화',address:'사업장 주소',contactEmail:'문의 이메일',contactPhone:'문의 전화',supportEmail:'고객 문의',supportContact:'고객 문의',contact:'연락처',refundPolicy:'환불·청약철회',deliveryTerms:'콘텐츠 제공 조건',financialRetention:'거래기록 보관',refundSummary:'환불·청약철회',transactionRetention:'거래기록 보관',transactionRetentionPolicy:'거래기록 보관',terms:'이용 조건'};const links=['termsUrl','privacyUrl'].map(k=>{try{const u=new URL(legal[k]);return u.protocol==='https:'?'<p><a class="inline-button" href="'+esc(u.href)+'" target="_blank" rel="noopener noreferrer">'+(k==='termsUrl'?'이용약관':'개인정보처리방침')+'</a></p>':'';}catch{return '';}}).join('');return links+Object.entries(labels).filter(([k])=>typeof legal[k]==='string'&&legal[k].trim()).map(([k,label])=>'<h3>'+label+'</h3><p>'+esc(legal[k])+'</p>').join('')||'<p>아직 상세 사업자·거래 조건이 제공되지 않았습니다. 실제 결제는 준비가 끝난 후 제공됩니다.</p>';}
function terms(){openDialog('<h2 id="dialog-title">이용·결제 안내</h2><div class="dialog-content"><h3>하나의 결과만 여는 결제</h3><p>익명 브라우저의 첫 생성 1건 부분 미리보기는 무료이며, 개인당 1회 인증은 아닙니다. 그 결과 1건의 전문 열람·편집·복사·저장은 3,000원(KRW)입니다. 계정 가입·구독·자동 결제 없이 이용하며, 새 글 생성·재검수는 포함하지 않습니다.</p><h3>제공·보관·환불</h3><p>결제 승인 확인 후 디지털 콘텐츠 전문을 즉시 제공합니다. 일반 미결제 결과는 최대 24시간, 결제 승인 확인 대기 결과는 최대 7일, 승인된 결과는 승인일부터 7일 보관합니다.</p><p>제공 개시 후에는 관련 법령의 요건을 충족한 범위에서 청약철회가 제한될 수 있습니다. 모든 환불을 배제하는 뜻은 아니며 미제공·중복 결제·결제 오류는 약관의 문의처로 요청해주세요. 내용 삭제는 환불이 아니고 무료 한도를 초기화하지 않습니다.</p><h3>이미 결제했는데 열리지 않나요?</h3><p>다시 결제하지 말고 이전 결과 불러오기 또는 같은 결제 승인 다시 확인을 이용해주세요. 자세한 사업자 정보·처리 조건은 아래 페이지에서 확인할 수 있습니다.</p></div><nav class="policy-links dialog-policy-links" aria-label="정책 전문">'+policyLinks()+'</nav>');}
function checkoutDialog(){if(!canPay()||P.busy)return;openDialog('<h2 id="dialog-title">이 결과 1건의 전문 열람</h2><p><b>결제금액 3,000원(KRW)</b> · 구독·자동 결제 없음</p>'+(paymentMode()==='test'?'<div class="notice warning">테스트 결제입니다. 실제 구매·청구가 아닙니다.</div>':'')+'<div class="dialog-content">'+legalHtml()+'</div><label class="check-line consent"><input id="terms-accepted" type="checkbox"><span>이용·결제 조건과 환불 안내를 확인하고 동의합니다. <a class="inline-button" href="/terms.html" target="_blank" rel="noopener noreferrer">이용약관·환불 안내<span class="sr-only"> (새 창)</span></a></span></label><label class="check-line consent"><input id="delivery-accepted" type="checkbox"><span>결제 승인 후 디지털 콘텐츠 전문의 즉시 제공에 동의합니다. 제공 개시 후에는 법령에 따라 청약철회가 제한될 수 있음을 확인했습니다.</span></label><p class="fineprint">결과 삭제는 환불이 아닙니다. 법령상 보장되는 환불 권리는 이 동의로 배제되지 않습니다. 미제공·중복 결제·결제 오류는 약관의 사업자 문의처로 요청해주세요.</p><p id="checkout-error" class="field-error" role="alert"></p><div class="button-row"><button class="button primary" data-action="pay">'+(paymentMode()==='test'?'테스트 결제창 열기':'3,000원 결제창 열기')+'</button><button class="button secondary" data-action="close-dialog">돌아가기</button></div>');}
function acceptResult(data){
 const r=data?.result||data;
 if(!isResultId(r?.resultId)||!['preview','full'].includes(r.access)||!Array.isArray(r.sections)||!r.sections.length)throw new Error('INVALID_RESULT');
 if(r.access==='preview'){
  if(r.sections.some(s=>typeof s.heading!=='string'||!Array.isArray(s.segments)||s.segments.some(x=>!['visible','locked'].includes(x.kind)||(x.kind==='visible'&&typeof x.text!=='string'))))throw new Error('INVALID_RESULT');
  // Explicit projection: never retain unexpected full text or detailed analysis in preview state.
  S.result={resultId:r.resultId,access:'preview',sections:r.sections.map(s=>({id:s.id,heading:s.heading,charCount:s.charCount,charLimit:s.charLimit,segments:s.segments.map(x=>x.kind==='visible'?{kind:'visible',text:x.text}:{kind:'locked',lines:x.lines})})),quality:{checks:(r.quality?.checks||[]).map(c=>({label:c.label,status:c.status}))},note:r.note,purchase:r.purchase};
 }else{if(r.sections.some(s=>typeof s.text!=='string'))throw new Error('INVALID_RESULT');S.result=clone(r);}
 rememberResult(r.resultId);S.hadGenerated=true;server.freeAvailable=false;S.edited=false;
}
async function paymentRequest(body,query=''){
 const abort=new AbortController();const timeout=setTimeout(()=>abort.abort(),60000);
 try{const response=await fetch('/api/payment'+query,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:abort.signal});let data;try{data=await response.json();}catch{throw new Error('PAYMENT_RESPONSE');}if(!response.ok)throw Object.assign(new Error('PAYMENT_REQUEST'),{code:data.code,status:response.status});return data;}finally{clearTimeout(timeout);}
}
async function restoreResult(latest=false){if(P.busy||S.busy)return;const invalidatedId=S.resultInvalidated?S.result?.resultId:null;P.busy=true;P.error='';P.message='';if(!S.result)route('payment');else render();try{const id=latest?null:(S.result?.resultId||savedResultId()||server.latestResultId);let data;try{data=await paymentRequest(null,isResultId(id)?'?resultId='+encodeURIComponent(id):'');}catch(e){if(e.status===404&&isResultId(id))data=await paymentRequest();else throw e;}acceptResult(data);P.message='서버에서 결과와 이용 권한을 확인했어요.';S.resultInvalidated=invalidatedId===S.result.resultId;S.error=null;S.pending=null;S.view='result';}catch(e){P.error=e.status===404||e.status===410?'이 브라우저에서 불러올 결과가 없거나 보관 기한이 지났어요. 결제한 결과가 있다면 복구코드를 사용해주세요.':'결과를 확인하지 못했어요. 결제했다면 다시 결제하지 말고 잠시 후 상태를 확인하거나 복구코드를 사용해주세요.';}finally{P.busy=false;render();}}
let sdkPromise;
function loadPaymentSdk(){if(window.TossPayments)return Promise.resolve(window.TossPayments);if(!sdkPromise)sdkPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://js.tosspayments.com/v2/standard';script.async=true;script.onload=()=>window.TossPayments?resolve(window.TossPayments):reject(new Error('SDK'));script.onerror=()=>{script.remove();sdkPromise=null;reject(new Error('SDK'));};document.head.append(script);});return sdkPromise;}
async function launchPayment(){if(!canPay()||P.busy)return;if(!$('#terms-accepted')?.checked||!$('#delivery-accepted')?.checked){$('#checkout-error').textContent='이용·결제 조건과 즉시 제공 동의를 모두 확인해주세요.';return;}P.busy=true;P.error='';P.message='';$('#dialog').close();render();try{
 const order=await paymentRequest({action:'create',resultId:S.result.resultId,termsAccepted:true,immediateDeliveryAccepted:true});
 if(order.amount!==3000||order.currency!=='KRW'||!['test','live'].includes(order.mode)||typeof order.orderId!=='string'||typeof order.clientKey!=='string')throw new Error('ORDER');
 const success=new URL(order.successUrl),fail=new URL(order.failUrl);if(success.origin!==location.origin||fail.origin!==location.origin||success.pathname!=='/payment/success'||fail.pathname!=='/payment/fail')throw new Error('CALLBACK');
 const TossPayments=await loadPaymentSdk();const payment=TossPayments(order.clientKey).payment({customerKey:TossPayments.ANONYMOUS});
 P.leaving=true;
 await payment.requestPayment({method:'CARD',amount:{currency:'KRW',value:3000},orderId:order.orderId,orderName:order.orderName,successUrl:order.successUrl,failUrl:order.failUrl,card:{flowMode:'DEFAULT'}});
 }catch{P.leaving=false;P.error='결제창을 완료하지 못했어요. 결과는 유지됩니다. 결제 내역이 있다면 먼저 상태를 다시 확인해주세요.';}finally{P.busy=false;render();}}
async function confirmPayment(){if(P.busy)return;const cb=P.callback;if(!cb?.paymentKey||!cb.orderId||!Number.isInteger(cb.amount)||cb.amount!==3000){P.error='결제 확인 정보가 올바르지 않아요. 이전 결과를 불러와 결제 상태를 확인해주세요.';P.callback=null;S.view='payment';render();return;}P.busy=true;P.error='';S.view='payment';render();try{const data=await paymentRequest({action:'confirm',...cb});acceptResult(data);if(S.result.access!=='full')throw new Error('NOT_CONFIRMED');P.callback=null;S.resultInvalidated=false;P.message='결제 승인을 서버에서 확인했습니다.';S.view='result';}catch{P.error='승인 확인을 완료하지 못했어요. 다시 결제하지 마세요. 같은 결제 승인 다시 확인 또는 이전 결과 불러오기를 이용해주세요.';}finally{P.busy=false;render();}}
function recoverDialog(){openDialog('<h2 id="dialog-title">결제한 결과 복구하기</h2><p>결제 후 받은 복구코드를 붙여넣어주세요. 결과 ID만으로 다른 브라우저의 결과를 열 수는 없어요.</p><label class="field-label" for="recover-code">복구코드</label><input class="recovery-input" id="recover-code" type="password" autocomplete="off" spellcheck="false" maxlength="300" placeholder="복구코드 붙여넣기"><p class="fineprint">복구코드는 비밀번호입니다. 공유하지 마세요. URL이나 브라우저 저장소에 보관하지 않습니다.</p><p id="recover-error" class="field-error" role="alert"></p><button class="button primary" data-action="recover-submit">결제 확인하고 복구하기</button>');}
async function recoverResult(){if(P.busy)return;let code=$('#recover-code')?.value.trim();if(!code){$('#recover-error').textContent='복구코드를 붙여넣어주세요.';return;}P.busy=true;const button=$('[data-action="recover-submit"]');if(button)button.disabled=true;try{const data=await paymentRequest({action:'recover',recoveryCode:code});acceptResult(data);if(S.result.access!=='full')throw new Error('NOT_FULL');$('#dialog').close();S.resultInvalidated=false;S.error=null;P.error='';P.message='서버에서 결제 상태를 확인하고 결과를 복구했어요.';S.view='result';render();}catch{if($('#recover-error'))$('#recover-error').textContent='복구하지 못했어요. 코드와 보관 기한을 확인해주세요. 결제 상태를 확인할 수 없는 경우에도 잠시 후 다시 시도할 수 있어요.';}finally{code='';P.busy=false;if($('#recover-code'))$('#recover-code').value='';if(button)button.disabled=false;}}
function recoveryCodeDialog(){if(!canUseFull()||!S.result.recoveryCode)return;openDialog('<h2 id="dialog-title">내 결과의 복구코드</h2><p>다른 브라우저에서 결과를 찾을 때 사용합니다. 비밀번호 관리자 등 안전한 곳에 따로 보관하고 공유하지 마세요.</p><label class="field-label" for="saved-recovery">복구코드</label><input class="recovery-input" id="saved-recovery" type="text" readonly autocomplete="off" value="'+esc(S.result.recoveryCode)+'"><p class="fineprint">이 코드는 페이지 메모리에만 유지됩니다. 전문 복사·TXT 파일에는 포함되지 않아요.</p><button class="button primary" data-action="copy-recovery">복구코드만 복사</button>');}
function paymentPage(){return '<main id="main" class="workspace wrap"><section class="work-card recovery-page"><span class="pill">결과·결제 확인</span><h1 tabindex="-1">내 결과를 안전하게 다시 열어요.</h1><p class="question-helper">결제 여부와 이용 권한은 서버에서 확인합니다. 이미 결제했다면 새로 결제하지 말고 아래에서 결과를 찾아주세요.</p>'+paymentNotice()+'<div class="button-row"><button class="button primary" data-action="restore" '+(P.busy?'disabled':'')+'>이전 결과 불러오기</button><button class="button secondary" data-action="recover-dialog" '+(P.busy?'disabled':'')+'>복구코드로 찾기</button><button class="text-button" data-action="home">처음으로</button></div></section></main>';}
async function bootstrap(){S.view=P.callbackRoute?'payment':'home';render();await checkStatus();if(P.callbackRoute==='/payment/success')await confirmPayment();else if(P.callbackRoute==='/payment/fail')render();}
// Prevent copying only the preview region; keyboard navigation and the rest of the site remain usable.
document.addEventListener('copy',e=>{if(S.result?.access!=='preview')return;const selection=window.getSelection();const anchor=selection?.anchorNode?.parentElement;const focus=selection?.focusNode?.parentElement;if(e.target.closest?.('.preview-text')||anchor?.closest('.preview-text')||focus?.closest('.preview-text')){e.preventDefault();announce('부분 미리보기는 복사를 제공하지 않습니다.');}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action;if(!['restore','terms','checkout','pay','confirm-payment','recover-dialog','recover-submit','recovery-code','copy-recovery'].includes(action))return;e.preventDefault();if(S.busy)return;
 if(action==='restore')await restoreResult();
 if(action==='terms')terms();
 if(action==='checkout')checkoutDialog();
 if(action==='pay')await launchPayment();
 if(action==='confirm-payment')await confirmPayment();
 if(action==='recover-dialog'&&!P.busy)recoverDialog();
 if(action==='recover-submit')await recoverResult();
 if(action==='recovery-code')recoveryCodeDialog();
 if(action==='copy-recovery'&&canUseFull()&&S.result.recoveryCode)await copyText(S.result.recoveryCode);
});

history.replaceState({insosoe:true,view:'home',cursor:0},'');bootstrap();
